      en: ["The central dome of the Taj Mahal reaches a height of 35 meters.", "The white marble was sourced from the Makrana quarries in Rajasthan.", "Approximately 20,000 workers were involved in the construction.", "The building appears to change color depending on the time of day.", "Four minarets surround the main tomb, each over 40 meters tall.", "Shah Jahan's cenotaph is the only asymmetrical element in the complex."],
