      ro: ["Construcția a început în 1592", "Patrimoniu UNESCO din 2013", "Faimos pentru Sheesh Mahal", "Situat pe malul lacului Maota", "Construit din gresie și marmură", "Ganesh Pol este poarta principală"],
      en: ["Construction started in 1592", "UNESCO World Heritage since 2013", "Famous for the Sheesh Mahal", "Overlooks the Maota Lake", "Built of sandstone and marble", "Ganesh Pol is the iconic gate"],
