      ro: ["Fondat în anul 1459", "Situat la 122 metri deasupra orașului", "Ziduri de până la 36 metri înălțime", "Dispune de șapte porți (Pols)", "Muzeu impresionant în interior", "Vedere asupra orașului albastru Jodhpur"],
      en: ["Founded in the year 1459", "Set 122 meters above the city", "Walls reach up to 36 meters high", "Features seven massive gates", "Houses a world-class museum", "Overlooks the Blue City of Jodhpur"],
      es: ["Fundado en el año 1459", "Situado a 122 metros sobre la ciudad", "Murallas de hasta 36 metros de altura", "Cuenta con siete puertas (Pols)", "Impresionante museo en su interior", "Vistas a la ciudad azul de Jodhpur"],
      pt: ["Fundado no ano de 1459", "Localizado 122 metros acima da cidade", "Muralhas até 36 metros de altura", "Abriga sete portas (Pols)", "Museu impressionante no interior", "Vista para a cidade azul de Jodhpur"],
      fr: ["Fondé en 1459", "Situé à 122 mètres au-dessus de la ville", "Murailles jusqu'à 36 mètres de haut", "Comprend sept portes (Pols)", "Musée impressionnant à l'intérieur", "Vue sur la ville bleue de Jodhpur"],
