    descriptionAdvanced: {
      de: "Das Jatayu Earth's Center im Distrikt Kollam in Kerala beherbergt die weltweit größte Vogel-Skulptur. Das Monument stellt den mythologischen Vogel Jatayu aus dem Epos Ramayana dar, der laut Legende auf diesem Felsen landete, nachdem ihm vom Dämonenkönig Ravana die Flügel gestutzt wurden. Die Skulptur ist 61 Meter lang, 46 Meter breit und 21 Meter hoch. Entworfen wurde sie vom Bildhauer und Filmregisseur Rajiv Anchal, der über zehn Jahre an der Fertigstellung arbeitete. Der Park erstreckt sich über 65 Hektar und kombiniert Mythologie mit Ökotourismus und Abenteuersport. Besucher können den Gipfel des Jadayupara-Hügels mit einer Seilbahn erreichen, die einen Panoramablick auf die Westghats bietet. Im Inneren der Skulptur befindet sich ein digitales Museum und ein 6D-Kino, das die Geschichte von Jatayu erzählt.",
      hu: "A Kerala államban, Kollam körzetében található Jatayu Earth's Center ad otthont a világ legnagyobb madárszobrának. Az emlékmű a Ramayana eposz mitológiai madarát, Jatayut ábrázolja, aki a legenda szerint ezen a sziklán landolt, miután Ravana démonkirály levágta a szárnyait. A szobor 61 méter hosszú, 46 méter széles és 21 méter magas. A műalkotást Rajiv Anchal szobrász és filmrendező tervezte, aki több mint tíz évig dolgozott a megvalósításán. A 65 hektáros park a mitológiát, az ökoturizmust és a kalandsportokat ötvözi. A látogatók kötélpályán érhetik el a Jadayupara-domb tetejét, ahonnan panorámás kilátás nyílik a Nyugati-Ghatok hegyláncaira. A szobor belsejében digitális múzeum és 6D-s mozi mutatja be Jatayu történetét.",
      ro: "Centrul Jatayu Earth din districtul Kollam, Kerala, găzduiește cea mai mare sculptură de pasăre din lume. Monumentul o reprezintă pe Jatayu, pasărea mitologică din epopeea Ramayana, despre care legenda spune că a căzut pe această stâncă după ce regele demon Ravana i-a tăiat aripile. Sculptura are o lungime de 61 de metri, o lățime de 46 de metri și o înălțime de 21 de metri. A fost proiectată de sculptorul și regizorul de film Rajiv Anchal, care a lucrat peste zece ani la finalizarea ei. Parcul se întinde pe 65 de hectare și combină mitologia cu ecoturismul și sporturile de aventură. Vizitatorii pot ajunge în vârful dealului Jadayupara cu o telecabină ce oferă o vedere panoramică asupra munților Ghats de Vest. În interiorul sculpturii se află un muzeu digital și un cinema 6D care relatează povestea lui Jatayu.",
      en: "Jatayu Earth's Center, located in the Kollam district of Kerala, is home to the world's largest bird sculpture. The monument represents the mythological bird Jatayu from the Ramayana epic, who legend says landed on this very rock after his wings were clipped by the demon king Ravana while trying to save Sita. The massive sculpture measures 61 meters long, 46 meters wide, and 21 meters high. It was designed by sculptor and filmmaker Rajiv Anchal, who spent over a decade bringing the project to life. Spanning 65 acres, the park integrates mythology with ecotourism and adventure sports. Visitors can reach the hilltop site via a state-of-the-art cable car system that offers panoramic views of the Western Ghats. Inside the hollow body of the sculpture, there is a digital museum and a 6D theatre showcasing the legend of Jatayu.",
      es: "Jatayu Earth's Center es una atracción destacada en Kerala. Alberga la escultura de ave más grande del mundo, representando a Jatayu, un semidiós con forma de águila del Ramayana. Desde una perspectiva regional, el sitio representa la diversidad de Kerala. La escultura mide 61 metros de largo, 46 de ancho y 21 de alto. Es un ejemplo característico del turismo moderno en Kerala y de la India. Cultura K7 — Monumento y Patrimonio de la India.",
      pt: "O Jatayu Earth's Center é uma atração significativa em Kerala. Abriga a maior escultura de ave do mundo, representando Jatayu, um semideus com forma de águia do Ramayana. Do ponto de vista regional, o local representa a diversidade de Kerala. A escultura mede 61 metros de comprimento, 46 de largura e 21 de altura. É um exemplo característico do turismo moderno em Kerala e na Índia. Cultura K7 — Monumento e Património da Índia.",
      fr: "Le Jatayu Earth's Center est un site touristique majeur du Kerala. Il abrite la plus grande sculpture d'oiseau au monde, représentant Jatayu, le demi-dieu aigle de l'épopée du Ramayana. D'un point de vue régional, le lieu illustre la vitalité du Kerala. La sculpture mesure 61 mètres de long, 46 mètres de large et 21 mètres de haut. C'est un exemple emblématique du Kerala contemporain. Culture K7 — Monument et patrimoine de l'Inde.",
    },
