      ro: ["Cea mai mare sculptură de pasăre din lume (61 m lungime)", "Situată pe stânca Jadayupara la o altitudine de 305 metri", "Creată de sculptorul și regizorul Rajiv Anchal", "Construcția a durat mai mult de un deceniu", "Include un muzeu digital și un cinematograf 6D în interior", "Proiectul promovează turismul durabil în Kerala"],
      en: ["Holds the record for the world's largest bird sculpture", "Dimensions: 200ft long, 150ft wide, and 70ft tall", "Designed by renowned sculptor Rajiv Anchal", "Located 1,000 feet above sea level on Jadayupara rock", "Features a sophisticated cable car system for visitors", "The park includes an adventure zone with over 20 activities"],
      es: ["Jatayu Earth's Center está en Kerala y es una atracción famosa.", "La región atrae a numerosos visitantes de la India y del extranjero.", "La cultura local está vinculada a la identidad del estado de Kerala.", "Figura como punto de referencia en muchos mapas de la India."],
      pt: ["O Jatayu Earth's Center situa-se em Kerala e é uma atração famosa.", "A região atrai inúmeros visitantes da Índia e do estrangeiro.", "A cultura local está ligada à identidade do estado de Kerala.", "Figura como ponto de referência em muitos mapas da Índia."],
